    :return:
    The list of external link of the page
    """
def get_links(page_text: Any) -> object {
    import re;
    ragex = re.compile(r'\[\[.*?\]\]');
    l = ragex.findall(page_text);
    return [s[2:-2].split("|")[0] for s in l];
}

"""
    Convert a string to title case.

    Title case means that the first letter of each word is capitalized, and all other letters in the word are lowercase.

    Parameters
    ----------
    sentence: str
      String to be converted to title case

    Returns
    -------
    ret: str
      String converted to title case.

    Example
    -------
    >>> title_case('ThIS is a STRinG to BE ConVerTeD.')
    'This Is A String To Be Converted.'
    """
def title_case(sentence: Any) -> object {
    if not isinstance(sentence, str) {
        raise TypeError(
            ('Invalid input, type %s - Input must be type string' % `type(sentence))
        );
    }
    ret = sentence[0].upper();
    for i in range(1, len(sentence)) {
        if (sentence[(i - 1)] == ' ') {
            ret = ret + sentence[i].upper();
        } else {
            ret = ret + sentence[i].lower();
        }
    }
    return ret;
}

"""Converts metadata from CVAT format.

    Args:
        data (OrderedDict): CVAT annotation

    Returns:
        dict: Annotation metadata
    """
def get_metadata(data: Any) -> object {
    metadata = {};
    metadata['source_name'] = data['source'];
    metadata['frames_size'] = data['task']['size'];
    metadata['start_frame'] = data['task']['start_frame'];
    metadata['stop_frame'] = data['task']['stop_frame'];
    metadata['video_width'] = data['task']['original_size']['width'];
    metadata['video_height'] = data['task']['original_size']['height'];
    return metadata;
}

